<script setup lang="ts">
import { Plus, ArrowUpRight, Copy, Trash2, FileUp, FileText, Search } from 'lucide-vue-next'
import type { Article, Resource } from '@qinbian/shared'
const ctx=useQinbian(),items=ref<Article[]>([]),templates=ref<Resource[]>([]),query=ref(''),creating=ref(false),title=ref(''),templateId=ref(''),fileInput=ref<HTMLInputElement>(),importing=ref(false)
const filtered=computed(()=>items.value.filter(d=>d.title.toLowerCase().includes(query.value.toLowerCase())))
async function refresh(){items.value=await apiFetch('/api/documents')};onMounted(async()=>{try{await refresh();templates.value=await apiFetch('/api/resources',{query:{kind:'template'}})}catch(e){ctx.error(e)}})
async function create(){try{const d=await apiFetch<Article>('/api/documents',{method:'POST',body:templateId.value?{title:title.value||undefined,resourceId:templateId.value}:{title:title.value||'未命名文章',themeSetId:'mine',blocks:[]}});navigateTo('/documents/'+d.id)}catch(e){ctx.error(e)}}
async function clone(d:Article){try{await apiFetch('/api/documents/'+d.id+'/clone',{method:'POST'});await refresh();ctx.notify('已复制文章')}catch(e){ctx.error(e)}}
async function remove(d:Article){if(!confirm(`将“${d.title}”移到回收站？`))return;try{await apiFetch('/api/documents/'+d.id,{method:'DELETE'});await refresh()}catch(e){ctx.error(e)}}
async function importDraft(files:FileList|null){const file=files?.[0];if(!file)return;if(file.size>100*1024*1024){ctx.notify('草稿文件不能超过 100 MB',true);return}importing.value=true;try{const raw=JSON.parse(await file.text());const d=await apiFetch<Article>('/api/documents/import',{method:'POST',body:{...raw,title:file.name.replace(/\.json$/,'')}});ctx.notify('草稿已导入');navigateTo('/documents/'+d.id)}catch(e){ctx.error(e)}finally{importing.value=false;if(fileInput.value)fileInput.value.value=''}}
</script>
<template><div class="page">
 <header class="page-heading"><div><h1>文章</h1></div><div class="heading-actions"><button class="btn" :disabled="importing" @click="fileInput?.click()"><FileUp :size="16"/>{{importing?'正在导入…':'导入草稿'}}</button><button class="btn primary" @click="creating=true"><Plus :size="16"/>新建文章</button><input ref="fileInput" type="file" hidden accept="application/json,.json" @change="importDraft(($event.target as HTMLInputElement).files)"></div></header>
 <div class="list-toolbar"><span class="muted small">{{items.length}} 篇</span><label class="search-field"><Search :size="16"/><input v-model="query" placeholder="搜索文章" aria-label="搜索文章"></label></div>
 <div v-if="!filtered.length" class="empty-state"><FileText :size="40"/><h3>{{query?'没有匹配的文章':'还没有文章'}}</h3><p v-if="!query">从空白页或编排模板开始。</p><button v-if="!query" class="btn primary" @click="creating=true"><Plus :size="16"/>新建文章</button></div>
 <div class="document-list"><article v-for="d in filtered" :key="d.id"><span class="document-icon"><FileText :size="18"/></span><NuxtLink :to="'/documents/'+d.id" class="document-list-title"><h2>{{d.title}}</h2><p>{{formatDate(d.updatedAt)}}<span>·</span>{{d.blocks.length}} 个组件<span>·</span>{{ctx.themes.value.find(t=>t.id===d.themeSetId)?.name||'我的资源'}}</p></NuxtLink><button class="icon-button" :aria-label="'复制文章 '+d.title" title="复制" @click="clone(d)"><Copy :size="16"/></button><button class="icon-button" :aria-label="'删除文章 '+d.title" title="删除" @click="remove(d)"><Trash2 :size="16"/></button><NuxtLink :to="'/documents/'+d.id" class="icon-button" :aria-label="'打开文章 '+d.title" title="打开"><ArrowUpRight :size="18"/></NuxtLink></article></div>
 <UiModal v-if="creating" title="新建文章" @close="creating=false"><form class="form-stack" @submit.prevent="create"><label>标题<input v-model="title" placeholder="未命名文章" autofocus></label><label>起点<UiSelect v-model="templateId" :options="[{value:'',label:'空白页'},...templates.map(t=>({value:t.id,label:t.name+' · '+(t.data.blocks?.length||0)+' 个组件'}))]" aria-label="起点"/></label><div class="modal-actions"><button type="button" class="btn" @click="creating=false">取消</button><button class="btn primary">创建并打开</button></div></form></UiModal>
</div></template>
